begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where is_root),true);
update public.family_settings set restrict_gender_chat=false,chat_enabled=true,public_chat_enabled=true,private_chat_enabled=true;
update family_private.member_details set phone='+966500009201',gender='male',full_name='مرتضى علي سلمان اختبار' where id=auth.uid();
create temp table fixture as select gen_random_uuid() as member,gen_random_uuid() as female;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select member,member::text||'@example.invalid',now(),'{"full_name":"أحمد علي سليمان اختبار","phone":"+966500009202","gender":"male"}'::jsonb from fixture;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select female,female::text||'@example.invalid',now(),'{"full_name":"فاطمة علي سلمان اختبار","phone":"+966500009203","gender":"female","reference_name":"مرتضى علي سلمان اختبار","relationship":"father"}'::jsonb from fixture;
update public.profiles set status='active' where id in(select member from fixture union select female from fixture);
update public.profiles p set display_name=d.full_name from family_private.member_details d where p.id=d.id and p.id in(select member from fixture union select female from fixture);
create temp table results as select exists(select 1 from jsonb_array_elements(public.chat_search('أ')) x where x->>'id'=(select member::text from fixture)) as first_letter,exists(select 1 from jsonb_array_elements(public.chat_search('05000092')) x where x->>'id'=(select member::text from fixture)) as phone_prefix,exists(select 1 from jsonb_array_elements(public.family_action('similar')) x where x->>'id'=(select member::text from fixture) and (x->>'score')::numeric>=70) as similarity;
update public.family_settings set restrict_gender_chat=true;
alter table results add column gender_filter boolean;
update results set gender_filter=not exists(select 1 from jsonb_array_elements(public.chat_search('ف')) x where x->>'id'=(select female::text from fixture));
select public.family_action('link',jsonb_build_object('member',(select member from fixture),'relation','brother'));
alter table results add column tree_saved boolean;
update results set tree_saved=exists(select 1 from jsonb_array_elements(public.family_action('tree'))x where x->>'id'=(select member::text from fixture) and x->>'relation'='brother');
create temp table message_fixture as with i as(insert into family_private.chat_messages(sender_id,body,created_at) values(auth.uid(),'FAMILY_MESSAGE_TEST',now()-interval '10 seconds') returning id)select id from i;
select public.message_action('reply_send',jsonb_build_object('id',(select id from message_fixture),'message','REPLY_TEST'));
select public.message_action('edit',jsonb_build_object('id',(select id from message_fixture),'message','EDIT_TEST'));
alter table results add column message_edited boolean,add column reply_saved boolean;
update results set message_edited=exists(select 1 from jsonb_array_elements(public.chat_read(null,null))x where x->>'body'='EDIT_TEST' and x->>'edited_at' is not null),reply_saved=exists(select 1 from jsonb_array_elements(public.chat_read(null,null))x where x->>'body'='REPLY_TEST' and (x->>'reply_to')::bigint=(select id from message_fixture));
select public.message_action('delete',jsonb_build_object('id',(select id from message_fixture)));
alter table results add column deleted_message boolean;
update results set deleted_message=exists(select 1 from jsonb_array_elements(public.chat_read(null,null))x where (x->>'id')::bigint=(select id from message_fixture) and x->>'deleted_at' is not null);
select set_config('request.jwt.claim.sub',(select member::text from fixture),true);
alter table results add column tree_isolated boolean;
update results set tree_isolated=public.family_action('tree')='[]'::jsonb;
select * from results;
rollback;
